import {GROUP_CASES,GROUP_UNKNOWNS,groupPrompt,groupEquations} from './equal-groups-content.mjs';
import {groupState,currentGroupWork,chooseGroupCase,chooseGroupUnknown,moveGroupModel,setGroupInput,submitGroupAnswer,checkGroupArrangement,useGroupSupport,stepGroupExample,setGroupMethod,carryGroupWork,recoverGroupState,modelTray,arrangementFits} from './equal-groups-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=p=>p==='cafe'?'#cafe/groups':'#post/groups';
const home=p=>p==='cafe'?'#cafe':'#post';
const words=p=>p==='cafe'?{group:'plate',objects:'bites',object:'bite',host:'Pip',other:'Bramble',place:'The serving bench'}:{group:'bundle',objects:'ribbons',object:'ribbon',host:'Bramble',other:'Pip at the café',place:'Bramble’s ribbon bench'};
const names={total:'How many altogether?',each:'How many in each?',groups:'How many groups?'};
const short={total:'Altogether',each:'In each group',groups:'Number of groups'};
const btn=(action,label,disabled=false,kind='secondary',extra='')=>`<button type="button" class="${kind}" data-eg-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const dots=(n,ribbons=false)=>`<span class="eg-objects ${ribbons?'eg-ribbons':''}" aria-hidden="true">${Array.from({length:n},()=>'<i></i>').join('')}</span>`;
function unknownChoices(selected){return `<div class="eg-unknowns" role="group" aria-label="Choose what to find">${GROUP_UNKNOWNS.map(u=>`<button type="button" class="secondary" data-eg-unknown="${u}" aria-pressed="${u===selected}">${esc(short[u])}</button>`).join('')}</div>`;}
export function equalGroupEntry(place){return `<aside class="eg-entry" aria-label="Another way to explore equal groups"><p><strong>Same supplies. A new question.</strong><span>${place==='cafe'?'Share bites, then take your arrangement to Bramble.':'Make bundles, then bring the same quantities to the café.'}</span></p><a class="secondary" href="${route(place)}">${place==='cafe'?'Try the serving bench':'Try the ribbon bench'}</a></aside>`;}
function heading(place){const w=words(place);return `<header class="eg-heading"><a class="back" href="${home(place)}">← ${place==='cafe'?'Back to my café order':'Back to my delivery'}</a><h1>${w.place}</h1><p>${place==='cafe'?'Help Pip plan the welcome-back tables.':'Bramble needs equal ribbon bundles to mend the garden’s decorations.'} Your ${place==='cafe'?'guest and plate':'delivery and other challenges'} will wait.</p></header>`;}
function chooser(state,place){const s=groupState(state),u=s.selected[place].unknown;return `${heading(place)}<section class="eg-choose" aria-labelledby="eg-choose-title"><h2 id="eg-choose-title" tabindex="-1">What shall we find?</h2>${unknownChoices(u)}<p>Choose some supplies. Small and big ideas are all open.</p><div class="eg-case-grid">${GROUP_CASES.map(c=>{const q=groupPrompt(c,place,u);return `<button type="button" class="eg-case" data-eg-case="${c.id}"><strong>${esc(c.name)}</strong><span>${q.givens.map(g=>`${g.value} ${esc(g.label).toLowerCase()}`).join(' · ')}</span><span>${esc(names[u])}</span></button>`;}).join('')}</div><p class="tiny">These are pretend practice supplies. They use no cupboard stock and don’t finish an order or open Bramble’s gate.</p></section>`;}
function modelPanel(c,model,d,place){
 const w=words(place),tray=modelTray(c,model),groups=model.groups,counters=!!d.support.counters,round=groups.length>0&&tray>=groups.length&&groups.every(n=>n<12);
 return `<section class="eg-bench" aria-labelledby="eg-model-title"><div class="eg-bench-heading"><h3 id="eg-model-title">Make the groups your way</h3>${btn('counters',counters?'Counters are showing':'Show the counters',counters,'text-button')}</div><div class="eg-tray" role="img" aria-label="Tray holding ${tray} ${w.objects}"><span class="eg-tray-label">The tray${counters?` · ${tray} ${w.objects}`:''}</span>${dots(tray,place==='bramble')}${tray===0?'<span class="eg-empty-tray">Everything is in the groups.</span>':''}</div><p class="eg-move-note">Tap to move one ${w.object}. ${place==='cafe'?'Plates':'Bundles'} can be unequal while you try things.</p><div class="eg-groups" role="group" aria-label="Your editable ${w.group} arrangement">${groups.map((count,i)=>`<section class="eg-group"><h4>${w.group[0].toUpperCase()+w.group.slice(1)} ${i+1}</h4><div class="eg-dish ${place==='bramble'?'eg-bundle':''}" role="img" aria-label="${w.group} ${i+1}: ${count} ${w.objects}">${dots(count,place==='bramble')}</div>${counters?`<p class="eg-group-count">${count} ${w.objects}</p>`:''}<div class="eg-group-controls">${btn('out','−1',count===0,'secondary',`data-eg-index="${i}" aria-label="Take one ${w.object} from ${w.group} ${i+1}"`)}${btn('in','+1',tray===0||count===12,'secondary',`data-eg-index="${i}" aria-label="Put one ${w.object} on ${w.group} ${i+1}"`)}</div>${d.unknown!=='each'?btn('scoop',`Add ${c.each} ${w.objects}`,tray<c.each||count+c.each>12,'text-button',`data-eg-index="${i}"`):''}${count===0?btn('remove-group',`Remove this empty ${w.group}`,false,'text-button',`data-eg-index="${i}"`):''}</section>`).join('')||`<p class="eg-no-groups">No ${w.group}s yet. Make one to get started.</p>`}</div><div class="eg-model-actions">${btn('add-group',`Add an empty ${w.group}`,groups.length===12)}${btn('round',`Share one to every ${w.group}`,!round)}${btn('reset','Put everything back on the tray',groups.every(n=>n===0),'text-button')}</div>${counters?`<p class="eg-readout">${groups.length} ${w.group}${groups.length===1?'':'s'} · ${c.total-tray} ${w.objects} in groups · ${tray} left on the tray</p>`:''}<div class="eg-check-row">${btn('check-model','Check my groups')}<p class="tiny">A check gives help; it never moves your supplies.</p></div></section>`;
}
function explanation(c,d,place){
 const w=words(place),step=d.exampleStep;
 return `<details class="eg-help" ${d.support.equations||step!==null&&step!==undefined?'open':''}><summary>Ideas to try together</summary><div class="eg-help-actions">${btn('equations','Show what these numbers mean',false,'secondary')}${btn('example','Try a smaller example',false,'secondary')}${btn('together','We are working together',!!d.support.together,'text-button')}</div>${d.support.equations?`<section class="eg-equations"><h3>One arrangement, related questions</h3><p>We’re finding: <strong>${esc(short[d.unknown])}</strong>.</p><p>${esc(groupPrompt(c,place,d.unknown).related)}</p>${groupEquations(c,place).map(line=>`<p>${esc(line)}</p>`).join('')}</section>`:''}${step!==null&&step!==undefined?`<section class="eg-example" aria-labelledby="eg-example-title"><h3 id="eg-example-title" tabindex="-1">A different example: two ${w.group}s</h3><p>This example uses 2 groups of 3. Your own supplies stay on the bench.</p><div class="eg-example-pictures" role="img" aria-label="${step===0?1:2} pictured ${w.group}s, three ${w.objects} in each">${dots(3,place==='bramble')}${step>0?dots(3,place==='bramble'):''}</div><p role="status">${step===0?`First, make one ${w.group} of 3 ${w.objects}.`:step===1?`Another equal ${w.group} makes 3 + 3 = 6 ${w.objects}.`:`2 groups × 3 in each = 6. Share 6 between 2 groups: 3 in each. Make groups of 3 from 6: 2 groups.`}</p><div class="eg-model-actions">${btn('example-back','Previous step',step===0)}${btn('example-next','Next step',step===2)}</div></section>`:''}</details>`;
}
export function equalGroupsPage(state,place,detail){
 const s=groupState(state);if(!s)return `${heading(place)}<section class="panel"><h2>These earlier supplies are kept safe.</h2><p>This version cannot use that bench notebook. The original is still in Grown-up notes. You can open a fresh bench and keep the earlier record.</p>${btn('recover','Start a fresh bench and keep the old notebook')}<a class="secondary" href="#notes">See the kept notebook</a></section>`;
 const x=currentGroupWork(state,place);if(detail==='choose'||!x)return chooser(state,place);
 const {case:c,unknown,model,work,draft}=x,w=words(place),d={...draft,unknown},q=groupPrompt(c,place,unknown),last=d.attempts.at(-1),fits=arrangementFits(c,model);
 return `<div class="eg-game ${place==='bramble'?'eg-at-bramble':''}">${heading(place)}<div class="eg-top-links"><a class="text-button" href="${route(place)}/choose">Choose other supplies</a><span>${esc(c.name)}</span></div><section class="eg-question" aria-labelledby="eg-question-title"><div class="eg-ticket"><span>${place==='cafe'?'Pip’s table note':'Bramble’s ribbon note'}</span><dl>${q.givens.map(g=>`<div><dt>${esc(g.label)}</dt><dd>${g.value}</dd></div>`).join('')}</dl></div><div><h2 id="eg-question-title" tabindex="-1">${esc(q.prompt)}</h2><p class="eg-equation">${esc(q.equation)}</p><div data-eg-audio>${hearButton(q.prompt,'Hear this question')}</div></div></section>${unknownChoices(unknown)}<div class="eg-mobile-audio" data-eg-audio>${hearButton(q.prompt,'Hear this question')}</div>${work.provenance?`<p class="eg-carried">These quantities came from ${work.provenance.source==='cafe'?'Pip’s serving bench':'Bramble’s ribbon bench'}. The arrangement is yours to change. Earlier work and help stay in the notebook.</p>`:''}<div class="eg-work-layout">${modelPanel(c,model,d,place)}<section class="eg-answer-panel" aria-labelledby="eg-answer-title"><h3 id="eg-answer-title">What do you think?</h3><form id="eg-answer-form" novalidate><label for="eg-answer">${esc(names[unknown])} (${esc(q.unit)})</label><div class="eg-answer-line"><input id="eg-answer" type="text" inputmode="numeric" autocomplete="off" maxlength="3" value="${esc(d.input)}" aria-describedby="eg-error"><button class="primary" type="submit">Try my answer</button></div><p id="eg-error" role="alert">${esc(d.error)}</p></form><p id="eg-feedback" role="status" tabindex="-1">${esc(d.feedback)}</p>${last?.correct&&!d.feedback&&/^\d{1,3}$/.test(d.input.trim())&&Number(d.input)===last.answer?`<p id="eg-last-answer">Your last answer, ${last.answer}, fits.${!fits?' The picture still has a different arrangement; you can change it without losing that answer.':''}</p>`:''}${last?`<fieldset class="eg-methods"><legend>About your last answer: how did you find it?</legend>${[['worked','I worked it out'],['counted','I counted'],['together','We did it together']].map(([id,label])=>`<button type="button" class="secondary" data-eg-method="${id}" aria-pressed="${d.method===id}">${label}</button>`).join('')}</fieldset>`:''}<p class="tiny">You can count, try again, ask for help, or pause. This is picture practice.</p>${explanation(c,d,place)}</section></div><section class="eg-carry"><div><h2>Same quantities. A different question.</h2><p>${w.other} can use this arrangement too. Your ${place==='cafe'?'café order':'delivery'} will wait here.</p></div>${btn('carry',`Visit ${w.other} with these supplies`,false,'primary')}<p class="tiny">Already have a bench waiting there? We’ll reopen it without changing its arrangement or answers.</p></section><details class="eg-talk"><summary>Something to wonder together</summary><p>What changed when we asked a new question? What stayed the same? Show someone which number means the whole collection, how many groups there are, and how much is in each.</p><p>This conversation is yours. Nothing is recorded or scored.</p></details></div>`;
}
export function equalGroupPairsShown(state,place){const x=currentGroupWork(state,place);return x?[[x.case.groups,x.case.each],...(x.draft.exampleStep!==null?[[2,3]]:[])]:[];}
export function bindEqualGroups(state,place,{save,render,navigate,focus}){
 if(!['cafe','bramble'].includes(place))return;
 const selecting=!!document.querySelector('.eg-choose');
 const refresh=(selector,fallback='#eg-model-title')=>{save();render();if(selector){const replacement=document.querySelector(selector);focus?.(!replacement||replacement.disabled?fallback:selector);}};
 const go=(hash,selector)=>{if(location.hash===hash){navigate(hash);focus?.(selector);}else{window.addEventListener('hashchange',()=>focus?.(selector),{once:true});navigate(hash);}};
 document.querySelectorAll('[data-eg-case]').forEach(b=>b.onclick=()=>{if(chooseGroupCase(state,place,b.dataset.egCase)){save();go(route(place),'#eg-question-title');}});
 document.querySelectorAll('[data-eg-unknown]').forEach(b=>b.onclick=()=>{if(chooseGroupUnknown(state,place,b.dataset.egUnknown))refresh(selecting?'#eg-choose-title':'#eg-question-title');});
 document.querySelectorAll('[data-eg-action]').forEach(b=>b.onclick=()=>{
  const action=b.dataset.egAction,index=Number(b.dataset.egIndex);let ok;
  if(action==='carry'){const result=carryGroupWork(state,place);if(result){save();go(route(result.target),'#eg-question-title');}return;}
  if(action==='recover'){if(recoverGroupState(state))refresh('#eg-choose-title');return;}
  if(['counters','equations','example','together'].includes(action))ok=useGroupSupport(state,place,action);
  else if(action==='example-back'||action==='example-next')ok=stepGroupExample(state,place,action==='example-next'?1:-1);
  else if(action==='check-model')ok=checkGroupArrangement(state,place);
  else ok=moveGroupModel(state,place,action,index);
  if(ok){const selector=action==='remove-group'||b.disabled?'#eg-model-title':action.startsWith('example')?'#eg-example-title':action==='check-model'?'#eg-feedback':b.hasAttribute('data-eg-index')?`[data-eg-action="${action}"][data-eg-index="${index}"]`:`[data-eg-action="${action}"]`;refresh(selector,action.startsWith('example')?'#eg-example-title':'#eg-model-title');}
 });
 document.querySelector('#eg-answer')?.addEventListener('input',e=>{setGroupInput(state,place,e.target.value);save();for(const id of ['#eg-feedback','#eg-error']){const element=document.querySelector(id);if(element)element.textContent='';}document.querySelector('#eg-last-answer')?.remove();});
 document.querySelector('#eg-answer-form')?.addEventListener('submit',e=>{e.preventDefault();submitGroupAnswer(state,place);refresh(currentGroupWork(state,place)?.draft.error?'#eg-answer':'#eg-feedback');});
 document.querySelectorAll('[data-eg-method]').forEach(b=>b.onclick=()=>{if(setGroupMethod(state,place,b.dataset.egMethod))refresh(`[data-eg-method="${b.dataset.egMethod}"]`);});
 document.querySelectorAll('[data-eg-audio] button').forEach(b=>b.addEventListener('click',()=>{useGroupSupport(state,place,'audio');save();}));
}
export function equalGroupsNotes(state){
 if(!Object.hasOwn(state,'equalGroups'))return '';const s=groupState(state);
 if(!s)return `<details class="panel"><summary>Earlier equal-group bench notebook</summary><p>Unknown format kept unchanged. You can keep it while opening a fresh bench.</p><pre>${esc(JSON.stringify(state.equalGroups,null,2))}</pre></details>`;
 const records=GROUP_CASES.flatMap(c=>['cafe','bramble'].flatMap(p=>{const w=s.cases[c.id]?.[p];return w?[[c,p,w]]:[];}));
 return `<details class="panel"><summary>Same supplies, different questions (${records.length} benches)</summary><p>All attempts are guided visual practice. Known quantities, model moves, counters, examples, narration, prior help and familiarity stay separate. A new setting never copies a successful answer or certifies independent transfer. Conversation prompts are unscored. Up to 24 attempts per question remain.</p>${records.map(([c,p,w])=>`<section><h3>${esc(c.name)} · ${p==='cafe'?'Café':'Bramble'}</h3><p>${c.groups} groups × ${c.each} in each = ${c.total} objects.</p>${w.provenance?`<p>Carried from ${esc(w.provenance.source)}; source question: ${esc(w.provenance.unknown)}. Source arrangement and help are kept below.</p>`:''}<pre>${esc(JSON.stringify(w,null,2))}</pre></section>`).join('')}${Object.hasOwn(s,'recovered')?`<h3>Earlier record kept in full</h3><pre>${esc(JSON.stringify(s.recovered,null,2))}</pre>`:''}</details>`;
}
